const SCRIPT: Plan = {"wilds":{"R1 kid1":0,"R1 kid2":1,"R1 mat1":1,"R1 mat2":1,"R1 oh1":1,"R1 oh2":1,"R1 boss":1,"R2 kid1":0,"R2 kid2":1,"R2 mat1":1,"R2 mat2":1,"R2 oh1":1,"R2 oh2":1,"R2 boss":1,"R3 kid1":0,"R3 kid2":1,"R3 mat1":1,"R3 mat2":1,"R3 oh1":1,"R3 oh2":1,"R3 boss":1},"nm":{"R1 kid2":2,"R1 mat2":3,"R1 boss":6,"R2 kid1":4,"R2 oh1":5,"R2 boss":6,"R3 kid2":6,"R3 oh2":6,"R3 boss":3},"buys":[{"at":"R1 kid1","phase":"pre","slot":0},{"at":"R1 kid1","phase":"post","slot":0},{"at":"R1 kid1","phase":"post","slot":1},{"at":"R1 kid1","phase":"post","slot":2},{"at":"R1 kid1","phase":"post","slot":3},{"at":"R1 kid2","phase":"post","slot":0},{"at":"R1 mat1","phase":"post","slot":0},{"at":"R1 mat1","phase":"post","slot":1},{"at":"R1 mat2","phase":"post","slot":0},{"at":"R1 mat2","phase":"post","slot":2},{"at":"R1 mat2","phase":"post","slot":3},{"at":"R1 oh1","phase":"post","slot":0},{"at":"R2 kid1","phase":"pre","slot":0},{"at":"R2 kid1","phase":"pre","slot":1},{"at":"R2 kid1","phase":"pre","slot":2},{"at":"R2 kid1","phase":"pre","slot":3},{"at":"R2 mat1","phase":"post","slot":0},{"at":"R2 mat1","phase":"post","slot":1},{"at":"R2 mat1","phase":"post","slot":2},{"at":"R2 mat1","phase":"post","slot":3},{"at":"R2 mat2","phase":"post","slot":0},{"at":"R2 mat2","phase":"post","slot":1},{"at":"R2 mat2","phase":"post","slot":2},{"at":"R2 mat2","phase":"post","slot":3},{"at":"R3 kid1","phase":"pre","slot":0},{"at":"R3 kid1","phase":"pre","slot":1},{"at":"R3 kid1","phase":"pre","slot":2},{"at":"R3 kid1","phase":"pre","slot":3},{"at":"R3 mat1","phase":"post","slot":0},{"at":"R3 mat1","phase":"post","slot":1},{"at":"R3 mat1","phase":"post","slot":2},{"at":"R3 mat1","phase":"post","slot":3},{"at":"R3 mat2","phase":"post","slot":0},{"at":"R3 mat2","phase":"post","slot":1},{"at":"R3 mat2","phase":"post","slot":2},{"at":"R3 mat2","phase":"post","slot":3}]};
const PY_MAIN: [string, number, number, number | null, number, number][] = [["R1 kid1",3000,3000.0,45.1,50.0,15350.0],["R1 kid2",3081.0,3081.0,35.3,977.5,13627.5],["R1 mat1",3136.0,3136.0,37.2,1045.0,11645.0],["R1 mat2",3230.0,3230.0,59.5,1390.0,8590.0],["R1 oh1",3285.0,3285.0,58.0,2457.5,6607.5],["R1 oh2",3340.0,3340.0,57.8,3525.0,4625.0],["R1 boss",3487.0,3535.0,89.8,10750.0,0.0],["R2 kid1",3535.0,3583.0,92.2,12190.0,0.0],["R2 kid2",3617.0,3665.0,81.5,13972.5,0.0],["R2 mat1",3699.0,3747.0,80.0,12680.0,0.0],["R2 mat2",3781.0,3829.0,75.3,187.5,0.0],["R2 oh1",3923.0,3971.0,89.1,6857.5,0.0],["R2 oh2",4005.0,4053.0,89.5,10365.0,0.0],["R2 boss",4060.0,4227.0,91.1,23992.5,0.0],["R3 kid1",4060.0,4227.0,84.2,21502.5,0.0],["R3 kid2",4232.0,4399.0,91.9,28050.0,0.0],["R3 mat1",4320.0,4487.0,92.8,24167.5,0.0],["R3 mat2",4408.0,4575.0,90.5,2685.0,0.0],["R3 oh1",4496.0,4663.0,90.3,6802.5,0.0],["R3 oh2",4628.0,4835.0,96.5,15375.0,0.0],["R3 boss",4628.0,5000.0,92.4,29145.0,0.0]];

const DNAME: Record<string, string> = { street: "Street", wangan: "Wangan", touge: "Touge" };
const RUNG_NAME: Record<string, string> = { kid1: "Kid 1", kid2: "Kid 2", mat1: "Mature 1", mat2: "Mature 2", oh1: "Old head 1", oh2: "Old head 2", boss: "Boss" };
const money = (x: number) => "$" + Math.round(x).toLocaleString("en-US");
const moneyS = (x: number) => (x > 0.005 ? "+" : x < -0.005 ? "−" : "") + money(Math.abs(x));
const pc = (x: number | null) => (x === null ? "—" : x.toFixed(1) + "%");
const toneOf = (w: number): "success" | "warning" | "danger" => (w >= 60 ? "success" : w >= 50 ? "warning" : "danger");
const raceName = (id: string) => { const p = id.split(" "); return p[0] + " " + RUNG_NAME[p[1]]; };
const slotText = (s: Slot) => (s ? "R" + (s[0] + 1) + " Mk" + s[1] + " · " + s[2].toFixed(1) + " / " + C.TIER[s[0]][s[1] - 1] : "empty (stock part)");
const list = (a: number[], f: (x: number) => string = String) => a.map(f).join(" / ");

// Keep the clicked control still: a re-render remounts tables and updates Metrics / LineChart
// and the inspector, which otherwise jumps the scroll. Pin any click on a [data-pin] node.
const pinId = (id: string) => "pin-" + id.replace(/\s+/g, "-");
type ScrollPin = { id: string; y: number; spots: { top: number; left: number; set: (t: number, l: number) => void }[] };
function pinNode(id: string): HTMLElement | null {
  return typeof document === "undefined" ? null : document.getElementById(id);
}
function scrollSpots(from: Element | null): ScrollPin["spots"] {
  const spots: ScrollPin["spots"] = [];
  const seen = new Set<Element | Window>();
  const addWin = () => {
    if (seen.has(window)) return;
    seen.add(window);
    spots.push({ top: window.scrollY, left: window.scrollX, set: (t, l) => window.scrollTo(l, t) });
  };
  const addEl = (node: Element) => {
    if (seen.has(node)) return;
    seen.add(node);
    const el = node as HTMLElement;
    spots.push({ top: el.scrollTop, left: el.scrollLeft, set: (t, l) => { el.scrollTop = t; el.scrollLeft = l; } });
  };
  addWin();
  let n: Element | null = from;
  while (n) {
    const st = getComputedStyle(n);
    if (/(auto|scroll|overlay)/.test(st.overflowY) || /(auto|scroll|overlay)/.test(st.overflowX)) addEl(n);
    n = n.parentElement;
  }
  return spots;
}
function capturePin(id: string, ev?: any): ScrollPin {
  const t: Element | null = ev && ev.currentTarget ? ev.currentTarget : ev && ev.target ? ev.target : null;
  const node: Element | null = (t && t.closest ? t.closest("[data-pin]") : null) || pinNode(id);
  return { id, y: node ? node.getBoundingClientRect().top : 0, spots: scrollSpots(node || t) };
}
function applyPin(pin: ScrollPin, node?: Element | null) {
  const el = node || pinNode(pin.id);
  for (const s of pin.spots) s.set(s.top, s.left);
  if (!el) return;
  const dy = el.getBoundingClientRect().top - pin.y;
  if (Math.abs(dy) < 1) return;
  let n: Element | null = el.parentElement;
  while (n) {
    const st = getComputedStyle(n);
    if (/(auto|scroll|overlay)/.test(st.overflowY) && (n as HTMLElement).scrollHeight > (n as HTMLElement).clientHeight + 1) {
      (n as HTMLElement).scrollTop += el.getBoundingClientRect().top - pin.y;
    }
    n = n.parentElement;
  }
  const dy2 = el.getBoundingClientRect().top - pin.y;
  if (Math.abs(dy2) >= 1) window.scrollBy(0, dy2);
}

export default function ModSkillPlanner() {
  const theme = useGrokTheme();
  const [wilds, setWilds] = useState<Record<string, number>>({});
  const [nm, setNm] = useState<Record<string, number>>({});
  const [buys, setBuys] = useState<Buy[]>([]);
  const [sel, setSel] = useState<string>("R1 kid1");
  const [shopSlot, setShopSlot] = useState<string>("0");
  const [shopPhase, setShopPhase] = useState<string>("post");

  const plan: Plan = { wilds, nm, buys };
  const key = JSON.stringify(plan);
  const rows = useMemo(() => simulate(plan), [key]);
  const ver = useMemo(() => {
    const s = simulate(SCRIPT);
    let worstPts = 0, worstWin = 0, worstCash = 0, same = 0;
    PY_MAIN.forEach((p, i) => {
      const x = s[i];
      const dp = Math.max(Math.abs(x.points - p[1]), Math.abs(x.ledger - p[2])), dc = Math.max(Math.abs(x.cash - p[4]), Math.abs(x.debt - p[5]));
      const dw = p[3] === null || x.win === null ? (p[3] === x.win ? 0 : 999) : Math.abs(x.win - p[3]);
      worstPts = Math.max(worstPts, dp); worstWin = Math.max(worstWin, dw); worstCash = Math.max(worstCash, dc);
      if (dp < 0.001 && dw < 1e-9 && dc < 0.006) same++;
    });
    return { worstPts, worstWin, worstCash, same, n: PY_MAIN.length };
  }, []);

  const pinRef = useRef<ScrollPin | null>(null);
  const attachPin = (id: string) => (el: HTMLDivElement | null) => {
    const p = pinRef.current;
    if (el && p && p.id === id) applyPin(p, el);
  };
  useEffect(() => {
    const arm = (ev: any) => {
      if (ev.type === "keydown" && ev.key !== "Enter" && ev.key !== " ") return;
      const t: Element | null = ev && ev.target ? ev.target : null;
      const node: Element | null = t && t.closest ? t.closest("[data-pin]") : null;
      const id = node && (node as HTMLElement).id ? (node as HTMLElement).id : "pin-page";
      pinRef.current = capturePin(id, ev);
    };
    document.addEventListener("pointerdown", arm, true);
    document.addEventListener("keydown", arm, true);
    return () => {
      document.removeEventListener("pointerdown", arm, true);
      document.removeEventListener("keydown", arm, true);
    };
  }, []);
  const viewKey = [key, sel, shopSlot, shopPhase].join("|");
  useEffect(() => {
    const p = pinRef.current;
    if (!p) return;
    const run = () => { if (pinRef.current === p) applyPin(p); };
    run();
    const a = requestAnimationFrame(run);
    const b = requestAnimationFrame(() => requestAnimationFrame(run));
    const t = window.setTimeout(() => { run(); if (pinRef.current === p) pinRef.current = null; }, 160);
    return () => { cancelAnimationFrame(a); cancelAnimationFrame(b); window.clearTimeout(t); };
  }, [viewKey]);

  const idx = Math.max(0, rows.findIndex((r) => r.id === sel));
  const cur = rows[idx];
  const press = (pid: string, ev: any, fn: () => void) => { if (ev && ev.preventDefault) ev.preventDefault(); pinRef.current = capturePin(pid, ev); fn(); };
  const go = (i: number) => setSel(rows[Math.min(rows.length - 1, Math.max(0, i))].id);
  const isDefault = Object.keys(wilds).every((k) => !wilds[k]) && Object.keys(nm).every((k) => !nm[k]) && buys.length === 0 && sel === "R1 kid1";
  const reset = () => {
    if (!isDefault && typeof window !== "undefined" && typeof window.confirm === "function") {
      if (!window.confirm("Reset the planner? This clears the wild encounters, non-mandatory wins and buys.")) return;
    }
    setWilds({}); setNm({}); setBuys([]); setSel("R1 kid1"); setShopSlot("0"); setShopPhase("post");
  };
  const loadExample = () => {
    if (!isDefault && typeof window !== "undefined" && typeof window.confirm === "function") {
      if (!window.confirm("Replace all your choices with the verified example playthrough?")) return;
    }
    setWilds({ ...SCRIPT.wilds }); setNm({ ...SCRIPT.nm }); setBuys(SCRIPT.buys.slice());
  };

  function counter(r: Row, kind: "w" | "n", where: string): ReactNode {
    const src = kind === "w" ? wilds : nm; const set = kind === "w" ? setWilds : setNm;
    const n = src[r.id] || 0; const max = kind === "w" ? C.REQ_WILDS[r.j] : 999;
    const pid = pinId(r.id) + "-" + kind + "-" + where;
    if (kind === "w" && max === 0) return <span key={pid} style={{ color: theme.text.secondary }}>none needed</span>;
    return (
      <div key={pid} id={pid} data-pin={pid} ref={attachPin(pid)} style={{ display: "flex", alignItems: "center", gap: 6, flexWrap: "nowrap", overflowAnchor: "auto" }}>
        <Button label="−" variant="quiet" disabled={n === 0} onClick={(ev?: any) => press(pid, ev, () => set({ ...src, [r.id]: Math.max(0, n - 1) }))} />
        <span style={{ minWidth: 36, textAlign: "center", flex: "0 0 auto", color: theme.text.primary }}>{kind === "w" ? n + " / " + max : String(n)}</span>
        <Button label="+" variant="quiet" disabled={n >= max} onClick={(ev?: any) => press(pid, ev, () => set({ ...src, [r.id]: n + 1 }))} />
      </div>
    );
  }
  const issueTag = (r: Row) => r.errors.length
    ? <Status key={"i" + r.id} tone="danger">{r.errors[0] + (r.errors.length > 1 ? " (+" + (r.errors.length - 1) + ")" : "")}</Status>
    : <Status key={"i" + r.id} tone="success">OK</Status>;

  // ── inspector data ──
  const slotIdx = Math.min(C.SLOTS - 1, Math.max(0, Number(shopSlot) || 0));
  const shopLabel = (i: number) => {
    const s = cur.slots[i]; const [g, mk] = nextStep(s, cur.rnd);
    const next = mk > 3 ? "already Mk3" : "next R" + (g + 1) + " Mk" + mk + " · " + money((cur.ws ? C.PRICE_WS : C.PRICE)[g][mk - 1]);
    return "Slot " + (i + 1) + " · now " + slotText(s) + " · " + next;
  };
  const hereBuys = buys.map((b, i) => ({ b, i })).filter((x) => x.b.at === cur.id);
  const cashMoveRows = cur.moves.map((m) => [
    m.label, m.purse ? money(m.purse) : "—", m.toDebt ? moneyS(-m.toDebt) : "—", m.label === "On arrival" ? "—" : moneyS(m.net), money(m.cash), money(m.debt),
  ]);
  const slotRows = cur.slots.map((s, i) => ["Slot " + (i + 1), slotText(cur.slotsRace[i]), slotText(s)]);

  // ── campaign data ──
  const valid = rows.filter((r) => r.win !== null);
  const allValid = valid.length === rows.length;
  const low = valid.length ? valid.reduce((m, r) => ((r.win as number) < (m.win as number) ? r : m), valid[0]) : null;
  const bosses = rows.filter((r) => r.boss);
  const nmTot = rows.reduce((s, r) => s + r.nm, 0);
  const lostTot = rows.reduce((s, r) => s + r.lostX + r.lostW, 0);
  const issues = rows.reduce((s, r) => s + r.errors.length, 0);
  const last = rows[rows.length - 1];

  const raceRows = rows.map((r) => [
    <div key={"b" + r.id} id={pinId("sel-" + r.id)} data-pin={pinId("sel-" + r.id)} ref={attachPin(pinId("sel-" + r.id))} style={{ overflowAnchor: "auto" }}>
      <Button label={raceName(r.id)} variant={r.id === cur.id ? "primary" : "quiet"} onClick={(ev?: any) => press(pinId("sel-" + r.id), ev, () => setSel(r.id))} />
    </div>,
    DNAME[r.d] + " · " + r.T + " turns",
    counter(r, "w", "row"),
    counter(r, "n", "row"),
    r.skill.toFixed(3),
    String(Math.round(r.points)),
    { text: Math.round(r.ledger) + " / " + r.floor, tone: (r.ledger >= r.floor - 1e-9 ? "success" : "danger") as "success" | "danger" },
    r.win === null ? "—" : { text: pc(r.win), tone: toneOf(r.win) },
    money(r.cash),
    money(r.debt),
    issueTag(r),
  ]);

  return (
    <Page
      title="Campaign planner: mod_skill"
      summary={"The live mod_skill rules at sim commit " + C.COMMIT + " (release 0.5: player unlock at " + Math.round(100 * C.HEAT_RELEASE) + "%). You choose every required wild encounter, every non-mandatory win and every mod buy; floors lock a crew race until your earned XP reaches them. Win chance comes from new Monte Carlo tables run through the live sim, on the standard reading curve."}
      width="wide"
    >
      <Section heading="Setup" actions={<Button label="Reset" onClick={(ev?: any) => press("pin-setup", ev, reset)} />}>
        <div id="pin-setup" data-pin="pin-setup" ref={attachPin("pin-setup")} style={{ overflowAnchor: "auto" }}>
          <Text>{"Nothing is filled in for you. Per race you set the required wild encounters (" + C.REQ_WILDS.reduce((a: number, b: number) => a + b, 0) + " per round, one before every rung after Kid 1), any non-mandatory wins, and every buy at Reiko's. Missing wilds and races below their floor are flagged and show no win chance. The car runs on each district's tune, as the sim measures it: points re-assign freely at Reiko's."}</Text>
          <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginTop: 8 }}>
            <Button label="Load the verified example playthrough" onClick={(ev?: any) => press("pin-setup", ev, loadExample)} />
            <Button label="Reset" onClick={(ev?: any) => press("pin-setup", ev, reset)} />
          </div>
        </div>
      </Section>

      <Section heading={"Race inspector: " + raceName(cur.id)} id="race-inspector">
        <div id="pin-inspector" data-pin="pin-inspector" ref={attachPin("pin-inspector")} style={{ overflowAnchor: "auto" }}>
          <div id="pin-inspector-nav" data-pin="pin-inspector-nav" ref={attachPin("pin-inspector-nav")} style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "flex-end", overflowAnchor: "auto" }}>
            <Button label="← Previous" disabled={idx === 0} onClick={(ev?: any) => press("pin-inspector-nav", ev, () => go(idx - 1))} />
            <Select label="Race" options={rows.map((r) => ({ value: r.id, label: raceName(r.id) }))} value={cur.id} onChange={(v: string) => setSel(v)} />
            <Button label="Next →" disabled={idx === rows.length - 1} onClick={(ev?: any) => press("pin-inspector-nav", ev, () => go(idx + 1))} />
          </div>
          <div style={{ marginTop: 16 }}>
            <Metrics
              metrics={[
                { value: pc(cur.win), label: "Win chance", detail: cur.win !== null ? "Hardest track " + C.TRACK[cur.d] + " · " + cur.T + " turns" : "Locked: see the issues below", tone: cur.win === null ? "danger" : toneOf(cur.win) },
                { value: cur.skill.toFixed(3), label: "Reading skill (read-only)", detail: "Standard curve: race " + (Math.round((cur.skill - 0.6) / 0.2 * cur.N) + 1) + " of " + (cur.N + 1) + " in " + DNAME[cur.d] },
                { value: String(Math.round(cur.points)), label: "Car points", detail: "Stock " + C.STOCK.toLocaleString("en-US") + " + slot points · round cap " + C.CAP[cur.rnd].toLocaleString("en-US") },
                { value: cur.ledger.toFixed(0) + " / " + cur.floor, label: "Earned XP vs floor", detail: "Every XP point earned counts, even past a ceiling", tone: cur.ledger >= cur.floor - 1e-9 ? "success" : "danger" },
                { value: cur.crew.toFixed(2), label: "Crew stats", detail: "Fixed stat total of this " + RUNG_NAME[C.RUNGS[cur.j]] },
              ]}
            />
          </div>
          <div id="pin-inspector-extra" data-pin="pin-inspector-extra" ref={attachPin("pin-inspector-extra")} style={{ display: "flex", gap: 16, flexWrap: "wrap", alignItems: "center", overflowAnchor: "auto", marginTop: 16 }}>
            <span style={{ color: theme.text.primary }}>Required wild encounters</span>
            {counter(cur, "w", "insp")}
            <span style={{ color: theme.text.primary }}>Non-mandatory wins</span>
            {counter(cur, "n", "insp")}
            <span style={{ color: theme.text.secondary }}>{"Each pays " + money(C.WILD_PURSE[cur.rnd]) + " and " + C.WILD_XP[cur.rnd] + " XP (non-mandatory: XP only for the first " + C.NM_CAP + " this round; " + cur.nmw + " used after this stop)"}</span>
          </div>
          <div id="pin-inspector-cash" data-pin="pin-inspector-cash" ref={attachPin("pin-inspector-cash")} style={{ overflowAnchor: "auto", marginTop: 16 }}>
            <Table columns={["Cash pool at this stop", "Purse", "To Sabine (debt)", "Net", "Cash", "Debt left"]} rows={cashMoveRows} align={["start", "end", "end", "end", "end", "end"]} />
            <Text>{"Order at each stop: buys before the extra races, then the required wilds and non-mandatory wins, then the race, then the story purse and buys after the win, then the story XP (" + cur.xpW + "). While the " + money(C.DEBT) + " debt is open, " + Math.round(100 * C.DEBT_SHARE) + "% of each purse goes to Sabine."}</Text>
          </div>
          <Grid columns={2}>
            <div id="pin-inspector-shop" data-pin="pin-inspector-shop" ref={attachPin("pin-inspector-shop")} style={{ display: "flex", flexDirection: "column", gap: 12, overflowAnchor: "auto" }}>
              <Text>{"Reiko's shop · " + DNAME[cur.d] + " · Mk" + C.MK_PRE[cur.j] + " on sale before this race, Mk" + C.MK_POST[cur.j] + " after the win" + (cur.ws ? " · wholesale −" + Math.round(100 * C.WHOLESALE) + "%" : "")}</Text>
              <Select label="Slot" options={[0, 1, 2, 3].map((i) => ({ value: String(i), label: shopLabel(i) }))} value={String(slotIdx)} onChange={(v: string) => setShopSlot(v)} />
              <Segmented options={[{ value: "pre", label: "Before the extra races" }, { value: "post", label: "After the win" }]} value={shopPhase} onChange={(v: string) => setShopPhase(v)} />
              <Text>{"Cash on arrival " + money(cur.cashArrive) + ". A buy is one step: an empty or older slot takes this round's Mk1, otherwise the next Mk. Earned points carry over."}</Text>
              <Button label="Add buy" variant="primary" onClick={(ev?: any) => press("pin-inspector-shop", ev, () => setBuys([...buys, { at: cur.id, phase: shopPhase === "pre" ? "pre" : "post", slot: slotIdx }]))} />
              {hereBuys.length ? (
                <Table
                  columns={["Your buys here", ""]}
                  rows={hereBuys.map(({ b, i }) => ["Slot " + (b.slot + 1) + " · " + (b.phase === "pre" ? "before the extra races" : "after the win"), <Button key={"x" + i} label="Remove" variant="quiet" onClick={(ev?: any) => press("pin-inspector-shop", ev, () => setBuys(buys.filter((_, q) => q !== i)))} />])}
                />
              ) : null}
            </div>
            <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
              <Table columns={["Slot", "At the race", "After this race's XP"]} rows={slotRows} />
              <Text>{"XP goes to the owned slot with the most room first, then spills; what no slot can hold is lost from the car but still counts toward the floors. Lost here: extra races " + cur.lostX.toFixed(1) + ", story win " + cur.lostW.toFixed(1) + "."}</Text>
            </div>
          </Grid>
          {cur.errors.length ? <Callout tone="danger" lead="Issues at this race">{cur.errors.join(" · ")}</Callout> : null}
        </div>
      </Section>

      <Section heading="Race by race" id="race-by-race" caption="State at each crew race, after its buys before the extra races and the extra races themselves. Win chance is on the district's hardest live track. Cash and debt are after the win, the buys after it and the XP.">
        <Table columns={["Race", "District · length", "Required wilds", "Non-mandatory wins", "Skill", "Points", "Earned / floor", "Win", "Cash", "Debt", "Issues"]} rows={raceRows} align={["start", "start", "start", "start", "end", "end", "end", "end", "end", "end", "start"]} />
      </Section>

      <Section heading="Standard reading curve" caption="Read-only placeholder. In each district, reading (read, QTE timing and pacing together) starts at 0.600 and climbs in a straight line with races run there, wilds and non-mandatory wins included, to 0.800 at the boss.">
        <div style={{ overflowAnchor: "none" }}>
          <LineChart points={rows.map((r) => ({ label: r.id, value: r.skill }))} ceiling={0.8} floor={0.6} format={(v: number) => v.toFixed(3)} labels={["Reading skill at each crew race"]} />
        </div>
      </Section>

      <Section heading="Campaign at a glance">
        <div style={{ overflowAnchor: "none" }}>
          <Metrics
            metrics={[
              { value: low ? pc(low.win) : "—", label: "Lowest race", detail: low ? raceName(low.id) + (allValid ? "" : " (unlocked races only)") : "No race is unlocked yet", tone: low ? toneOf(low.win as number) : "danger" },
              { value: bosses.map((r) => pc(r.win)).join(" / "), label: "Bosses R1 / R2 / R3" },
              { value: String(nmTot), label: "Non-mandatory wins", detail: "XP for the first " + C.NM_CAP + " per round" },
              { value: money(last.cash), label: "Cash after the R3 boss", detail: last.debt > 0 ? "Debt left " + money(last.debt) : "Debt cleared" },
              { value: lostTot.toFixed(0), label: "XP lost from the car", detail: "No owned slot had room" },
              { value: String(issues), label: "Open issues", detail: issues ? "See the Issues column" : "Every race is valid", tone: issues ? "danger" : "success" },
            ]}
          />
          {allValid ? <LineChart points={rows.map((r) => ({ label: r.id, value: r.win as number }))} ceiling={100} floor={0} unit="%" labels={["Win chance per crew race"]} /> : null}
        </div>
      </Section>

      <Section heading="Rules used" collapsible defaultOpen={false}>
        <Rows
          rows={[
            { title: "Source", detail: "Every number on this page is generated from the live sim at commit " + C.COMMIT + " (sim/velocity_shift/equations.py and mod_skill.py) by unapproved/barry/planner-v2/gen_constants.py. Player unlock (HEAT_RELEASE) " + C.HEAT_RELEASE + "." },
            { title: "Car", detail: "The " + C.STOCK.toLocaleString("en-US") + "-point stock car plus the earned points in its " + C.SLOTS + " mod slots, on the district tune. Round caps " + list(C.CAP, (x) => x.toLocaleString("en-US")) + "." },
            { title: "Mods", detail: "Slot ceilings by Mk1 / Mk2 / Mk3: R1 " + list(C.TIER[0]) + ", R2 " + list(C.TIER[1]) + ", R3 " + list(C.TIER[2]) + ". Mk1 is on sale at round open, Mk2 after the Mature 1 win, Mk3 after the Mature 2 win. List prices R1 " + list(C.PRICE[0], money) + ", R2 " + list(C.PRICE[1], money) + ", R3 " + list(C.PRICE[2], money) + "; wholesale −" + Math.round(100 * C.WHOLESALE) + "% in R2 and R3. A buy you can't afford, or one not on sale yet, is flagged and not applied." },
            { title: "XP", detail: "Story wins, Kid 1 … Boss: R1 " + list(C.STORY_XP[0]) + "; R2 " + list(C.STORY_XP[1]) + "; R3 " + list(C.STORY_XP[2]) + ". Wild encounters and non-mandatory wins: " + list(C.WILD_XP) + " by round; non-mandatory wins pay XP only for the first " + C.NM_CAP + " per round." },
            { title: "Required wilds and floors", detail: "Each rung after Kid 1 needs " + C.REQ_WILDS[1] + " required wild encounter win first (13 mandatory races per round). Floors, earned XP needed to challenge Kid 1 … Boss: Street " + list(C.FLOOR.street) + "; Wangan " + list(C.FLOOR.wangan) + "; Touge " + list(C.FLOOR.touge) + "." },
            { title: "Crew", detail: "Fixed crew stats, Kid 1 … Boss: Street " + list(C.CREW.street, (x) => x.toFixed(2)) + "; Wangan " + list(C.CREW.wangan, (x) => x.toFixed(2)) + "; Touge " + list(C.CREW.touge, (x) => x.toFixed(2)) + "." },
            { title: "Cash", detail: "Story purses by round: Kid " + list(C.PURSE.map((p: any) => p.kid), money) + ", crew " + list(C.PURSE.map((p: any) => p.mature), money) + ", boss " + list(C.PURSE.map((p: any) => p.boss), money) + ". Wilds and non-mandatory wins pay " + list(C.WILD_PURSE, money) + ". " + Math.round(100 * C.DEBT_SHARE) + "% of every purse repays the " + money(C.DEBT) + " debt until it is cleared. Every planned race is assumed won." },
            { title: "Win chance", detail: "Monte Carlo through the live sim (mod_skill.crew_config, hardest live track, 3 boss styles, " + C.N_MC.toLocaleString("en-US") + " races per cell, seeds from " + C.SEED.toLocaleString("en-US") + "), on a grid of reading " + list(WT.Q, (x) => x.toFixed(2)) + " × car points at every floor, the midpoint to the cap and the cap. Bilinear in between; points outside the grid use its edge. Pre-finale arc and finale are not modelled." },
          ]}
        />
      </Section>

      <Section heading="Verified against the Python model">
        <Table
          columns={["Scripted playthrough, 21 crew races", "Worst difference", ""]}
          rows={[
            ["Car points and earned XP", ver.worstPts.toFixed(3), <Status key="v1" tone={ver.worstPts < 0.001 ? "success" : "danger"}>{ver.worstPts < 0.001 ? "match" : "off"}</Status>],
            ["Win chance (pp)", ver.worstWin.toFixed(2), <Status key="v2" tone={ver.worstWin < 1e-9 ? "success" : "danger"}>{ver.worstWin < 1e-9 ? "match" : "off"}</Status>],
            ["Cash and debt ($)", ver.worstCash.toFixed(2), <Status key="v3" tone={ver.worstCash < 0.006 ? "success" : "danger"}>{ver.worstCash < 0.006 ? "match" : "off"}</Status>],
            ["Races matching on every field", ver.same + " of " + ver.n, <Status key="v4" tone={ver.same === ver.n ? "success" : "danger"}>{ver.same === ver.n ? "all" : "check"}</Status>],
          ]}
        />
        <Text>This page reruns the example playthrough with its own engine and compares it with the Python model, unapproved/barry/planner-v2/py_reference.py. The offline check, verify.mjs, compares 844 numbers over that playthrough plus an error-path plan (missing wild, floor lock, early Mk2, unaffordable and Mk3-maxed buys): all 844 match exactly, and the validation messages match too.</Text>
      </Section>
    </Page>
  );
}
